// ~/temporal-lab/src/activities.ts: activities may use the network, files and the clock
export async function greet(name: string): Promise<string> {
  console.log(`greet called for ${name}`); // so you can see when it really runs
  return `Hello, ${name}!`;
}

import { proxyActivities, sleep } from "@temporalio/workflow";
import type * as activities from "./activities.js";

const { greet } = proxyActivities<typeof activities>({ startToCloseTimeout: "1 minute" });

export async function hello(name: string): Promise<string> {
  const first = await greet(name); // the result is written to the history
  await sleep("30 seconds"); // a durable timer: stop the worker now
  const second = await greet(`${name} again`);
  return `${first} ${second}`;
}

import { fileURLToPath } from "node:url";
import { NativeConnection, Worker } from "@temporalio/worker";
import * as activities from "./activities.js";

const connection = await NativeConnection.connect({ address: "localhost:7233" });
const worker = await Worker.create({
  connection,
  namespace: "ai-agents",
  taskQueue: "ai-agents-lab",
  workflowsPath: fileURLToPath(new URL("./workflows.ts", import.meta.url)), // bundled for the sandbox
  activities, // plain functions, run as normal Node code
});
await worker.run(); // polls the task queue until you press Ctrl+C

import { Client, Connection } from "@temporalio/client";
import { hello } from "./workflows.js";

const connection = await Connection.connect({ address: "localhost:7233" });
const client = new Client({ connection, namespace: "ai-agents" });
const handle = await client.workflow.start(hello, {
  taskQueue: "ai-agents-lab",
  workflowId: "lab:RH-1", // the run's name; Nova uses nova:RH-1234
  args: ["Sean"],
});
console.log("started", handle.workflowId);
